const input = $input.first().json;
// Recover ticket fields from a normal webhook body or legacy nested webhook bodies.
const allowed = ['ticketId','title','description','category','priority','assignedTeam','status','createdAt','aiReason','aiSuggestion','suggestedResponse','deduplication','alert','sla','actor','eventId','updatedAt','source','categoryRationale','aiClassification','priorityReason','assignmentQueue','assignmentReason','assignment','prioritySignals','deduplication','stepTrace'];
const layers = [];
let value = input;
for (let depth = 0; depth < 16; depth++) {
  if (typeof value === 'string') value = JSON.parse(value);
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Ticket payload must be a JSON object');
  layers.push(value);
  if (!Object.prototype.hasOwnProperty.call(value, 'body')) break;
  value = value.body;
  if (depth === 15) throw new Error('Webhook body nesting is too deep');
}
const ticket = {};
const trace = [];
for (const layer of layers.reverse()) {
  for (const key of allowed) if (Object.prototype.hasOwnProperty.call(layer, key)) ticket[key] = layer[key];
  if (Array.isArray(layer.workflowTrace)) for (const entry of layer.workflowTrace.slice(-32)) {
    if (typeof entry === 'string' && entry.length <= 80 && !trace.includes(entry)) trace.push(entry);
  }
}
ticket.workflowTrace = trace.slice(-32);
if (JSON.stringify(ticket).length > 65536) throw new Error('Ticket payload exceeds the workflow size limit');
ticket._workflowTime = new Date().toISOString();
return [{ json: ticket }];

const input = $input.first().json;
const ticket = { ...input };
if (typeof ticket.ticketId !== 'string' || !ticket.ticketId.trim() || ticket.ticketId.length > 100) throw new Error('ticketId is required and must be at most 100 characters');
ticket.ticketId = ticket.ticketId.trim();
for (const key of ['title','description','category','priority','status','assignedTeam','aiReason','aiSuggestion','suggestedResponse']) {
  if (ticket[key] !== undefined && typeof ticket[key] !== 'string') throw new Error(key + ' must be a string');
}
if (ticket.title && ticket.title.length > 200) throw new Error('title is too long');
if (ticket.description && ticket.description.length > 10000) throw new Error('description is too long');

for (const key of ['createdAt','updatedAt']) {
 const value = ticket[key];
 if (value != null && ((!['string','number'].includes(typeof value)) || !Number.isFinite(new Date(value).getTime()))) throw new Error(key + ' must be a valid date');
}
return [{ json: ticket }];

const input = $input.first().json;
const names = { critical: 'Critical', high: 'High', medium: 'Medium', low: 'Low' };
const raw = String(input.priority ?? 'Medium').trim().toLowerCase();
if (!Object.prototype.hasOwnProperty.call(names, raw)) throw new Error('priority must be Critical, High, Medium, or Low');
return [{ json: { ...input, priority: names[raw] } }];

const input = $input.first().json;
const statusNames = { open: 'Open', 'in progress': 'In Progress', resolved: 'Resolved', closed: 'Resolved' };
const status = statusNames[String(input.status ?? 'Open').trim().toLowerCase()];
if (!status) throw new Error('status must be Open, In Progress, or Resolved');
const required = status !== 'Resolved' && ['Critical','High'].includes(input.priority);
return [{ json: { ...input, status, alert: { required, sent: false, reason: status === 'Resolved' ? 'Ticket is resolved' : required ? 'High or Critical priority requires attention' : 'Priority does not require an alert' } } }];

const input = $input.first().json;
const title = input.title || 'Ticket without a title';
const message = `[${input.priority}] ${input.ticketId}: ${title}. Assigned team: ${input.assignedTeam || 'IT General'}.`;
return [{ json: { ...input, alert: { ...input.alert, message } } }];

const input = $input.first().json;
const workflowTrace = [...(input.workflowTrace ?? [])];
if (!workflowTrace.includes('WF07')) workflowTrace.push('WF07');
return [{ json: { ...input, workflowTrace } }];

const input = $input.first().json;
if (typeof input.alert.required !== 'boolean' || input.alert.sent !== false) throw new Error('Invalid alert handoff');
if (input.createdAt !== undefined && !Number.isFinite(new Date(input.createdAt).getTime())) throw new Error('createdAt must be a valid date');
return [{ json: { ...input, assignedTeam: (input.assignedTeam || 'IT General').trim() || 'IT General' } }];

const input = $input.first().json;
const expectedTicketId = $('09 - Validate SLA Handoff').first().json.ticketId;
if (input.processingComplete !== true || !input.auditLog || typeof input.auditLog.eventId !== 'string') throw new Error('Downstream workflow did not return a completed audit event');
if (input.ticketId !== expectedTicketId || input.auditLog.ticketId !== expectedTicketId || input.auditLog.persisted !== true) throw new Error('Downstream ticketId does not match the audit event');
return [{ json: input }];
